nt as a file in the browser using FileSaver.js. Supports returning a Promise for asynchronous operations.\n\n```javascript\nAPI.save = function(filename, options) {\n  filename = filename || \"generated.pdf\";\n\n  options = options || {};\n  options.returnPromise = options.returnPromise || false;\n\n  // @if MODULE_FORMAT!='cjs'\n  if (options.returnPromise === false) {\n    saveAs(getBlob(buildDocument()), filename);\n    if (typeof saveAs.unload === \"function\") {\n      if (globalObject.setTimeout) {\n        setTimeout(saveAs.unload, 911);\n      }\n    }\n    return this;\n  } else {\n    return new Promise(function(resolve, reject) {\n      try {\n        var result = saveAs(getBlob(buildDocument()), filename);\n        if (typeof saveAs.unload === \"function\") {\n          if (globalObject.setTimeout) {\n            setTimeout(saveAs.unload, 911);\n          }\n        }\n        resolve(result);\n      } catch (e) {\n        reject(e.message);\n      }\n    });\n  }\n  // @endif\n\n  // @if MODULE_FORMAT='cjs'\n  // eslint-disable-next-line no-unreachable\n  var fs = require(\"fs\");\n  var buffer = Buffer.from(getArrayBuffer(buildDocument()));\n  if (options.returnPromise === false) {\n    fs.writeFileSync(filename, buffer);\n  } else {\n    return new Promise(function(resolve, reject) {\n      fs.writeFile(filename, buffer, function(err) {\n        if (err) {\n          reject(err);\n        } else {\n          resolve();\n        }\n      });\n    });\n  }\n  // @endif\n};\n```\n\n### jsPDF API Documentation > Page Management\n\nSource: https://github.com/parallax/jspdf/blob/master/docs/jspdf.js.html\n\nThe `addPage` method adds a new page to the PDF document. It accepts the page format (predefined like 'a4', 'letter', or custom dimensions) and orientation ('portrait' or 'landscape') as arguments. The method returns the jsPDF instance for chaining."
